const script = `
import configparser, json, subprocess, urllib.parse, urllib.request

def dexec(container, *args):
    return subprocess.check_output(["docker", "exec", container, *args], text=True)

def get_json(url, headers=None):
    req = urllib.request.Request(url, headers=headers or {})
    with urllib.request.urlopen(req, timeout=20) as response:
        return json.load(response)

sab_cfg = configparser.ConfigParser(interpolation=None)
sab_cfg.read_string(dexec("sabnzbd", "cat", "/config/sabnzbd.ini"))
sab_key = sab_cfg["misc"]["api_key"]

def sab(mode, **params):
    query = {"mode": mode, "output": "json", "apikey": sab_key}
    query.update(params)
    return get_json("http://172.20.1.20:8080/api?" + urllib.parse.urlencode(query))

lid_xml = dexec("lidarr", "cat", "/config/config.xml")
import re
lid_key = re.search(r"<ApiKey>([^<]+)</ApiKey>", lid_xml).group(1)
lid_headers = {"X-Api-Key": lid_key}

queue = sab("queue", limit=200)["queue"]
history = sab("history", limit=300)["history"]
lid_queue = get_json("http://172.20.1.25:8686/api/v1/queue?page=1&pageSize=200&includeUnknownArtistItems=true", lid_headers)
lid_history = get_json("http://172.20.1.25:8686/api/v1/history?page=1&pageSize=300&sortDirection=descending&sortKey=date", lid_headers)
lid_health = get_json("http://172.20.1.25:8686/api/v1/health", lid_headers)

sab_queue_fields = ["nzo_id","filename","cat","status","percentage","mb","mbleft","timeleft","avg_age","msg","unpackopts","priority"]
sab_history_fields = ["nzo_id","name","category","status","fail_message","storage","bytes","completed","download_time","postproc_time","url"]
lid_queue_fields = ["id","title","status","trackedDownloadStatus","trackedDownloadState","statusMessages","errorMessage","downloadId","protocol","size","sizeleft","timeleft","artist","album"]
lid_history_fields = ["id","sourceTitle","eventType","date","downloadId","quality","data","artistId","albumId"]

def pick(d, keys):
    return {k:d.get(k) for k in keys if k in d}

music_hist = [x for x in history.get("slots",[]) if str(x.get("category","")).lower()=="music" or x.get("status")!="Completed"]
recent_lid = []
for x in lid_history.get("records",[]):
    if x.get("eventType") in ("downloadFailed","downloadFolderImported","trackFileImported","trackFileRenamed") or x.get("downloadId"):
        recent_lid.append(pick(x,lid_history_fields))

print(json.dumps({
  "sab_queue_summary": pick(queue, ["status","speed","size","sizeleft","timeleft","noofslots","diskspace1","diskspace2","paused"]),
  "sab_queue": [pick(x,sab_queue_fields) for x in queue.get("slots",[])],
  "sab_music_or_failed_history": [pick(x,sab_history_fields) for x in music_hist[:100]],
  "lidarr_queue_total": lid_queue.get("totalRecords"),
  "lidarr_queue": [pick(x,lid_queue_fields) for x in lid_queue.get("records",[])],
  "lidarr_recent_relevant_history": recent_lid[:120],
  "lidarr_health": lid_health,
}, indent=2, default=str))
`;
